/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
#include "unity.h"
#include "storage_status.h"
#include <string.h>

static storage_status_t status;

void setUp(void)
{
    storage_status_init(&status);
}

void tearDown(void) {}

/* Helper: get a card all the way to READY with capacity and files. */
static void bring_card_to_ready(uint32_t total_kb, uint32_t free_kb, size_t files)
{
    storage_status_set_card_detected(&status, true);
    storage_status_set_mount_result(&status, STORAGE_OK);
    storage_status_set_capacity(&status, total_kb, free_kb);
    storage_status_set_file_count(&status, files);
}

/* ============ init ============ */

void test_init_starts_with_no_card(void)
{
    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
    TEST_ASSERT_EQUAL(STORAGE_OK, status.last_fault);
    TEST_ASSERT_EQUAL_UINT32(0U, status.total_kb);
    TEST_ASSERT_EQUAL_UINT32(0U, status.free_kb);
    TEST_ASSERT_EQUAL_UINT32(0U, status.file_count);
}

void test_init_handles_null_safely(void)
{
    storage_status_init(NULL); /* must not crash */
    TEST_PASS();
}

/* ============ card detection ============ */

void test_card_inserted_moves_to_present_unmounted(void)
{
    storage_status_set_card_detected(&status, true);
    TEST_ASSERT_EQUAL(CARD_PRESENT_UNMOUNTED, status.state);
}

void test_card_absent_stays_absent(void)
{
    storage_status_set_card_detected(&status, false);
    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
}

void test_reinserting_already_present_card_does_not_reset_ready_state(void)
{
    bring_card_to_ready(1000U, 500U, 3U);
    storage_status_set_card_detected(&status, true); /* pin re-read */
    TEST_ASSERT_EQUAL(CARD_READY, status.state);
    TEST_ASSERT_EQUAL_UINT32(3U, status.file_count);
}

void test_card_removal_clears_all_state(void)
{
    bring_card_to_ready(1000U, 500U, 5U);
    storage_status_set_card_detected(&status, false);

    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
    TEST_ASSERT_EQUAL_UINT32(0U, status.total_kb);
    TEST_ASSERT_EQUAL_UINT32(0U, status.free_kb);
    TEST_ASSERT_EQUAL_UINT32(0U, status.file_count);
}

void test_card_removal_while_faulted_clears_the_fault(void)
{
    bring_card_to_ready(1000U, 500U, 2U);
    storage_status_report_fault(&status, STORAGE_WRITE_FAIL);
    TEST_ASSERT_EQUAL(CARD_FAULT, status.state);

    storage_status_set_card_detected(&status, false);
    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
    TEST_ASSERT_EQUAL(STORAGE_OK, status.last_fault);
}

void test_remove_then_reinsert_requires_remount(void)
{
    bring_card_to_ready(1000U, 500U, 2U);
    storage_status_set_card_detected(&status, false);
    storage_status_set_card_detected(&status, true);

    /* Must NOT jump straight back to READY - the new card is unmounted. */
    TEST_ASSERT_EQUAL(CARD_PRESENT_UNMOUNTED, status.state);
    TEST_ASSERT_FALSE(storage_status_can_record(&status));
}

/* ============ mounting ============ */

void test_successful_mount_moves_to_ready(void)
{
    storage_status_set_card_detected(&status, true);
    storage_status_set_mount_result(&status, STORAGE_OK);
    TEST_ASSERT_EQUAL(CARD_READY, status.state);
}

void test_failed_mount_moves_to_fault_with_reason(void)
{
    storage_status_set_card_detected(&status, true);
    storage_status_set_mount_result(&status, STORAGE_CORRUPT);

    TEST_ASSERT_EQUAL(CARD_FAULT, status.state);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, status.last_fault);
}

void test_mount_attempt_with_no_card_is_ignored(void)
{
    storage_status_set_mount_result(&status, STORAGE_OK);
    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
}

void test_remount_after_fault_returns_to_ready(void)
{
    storage_status_set_card_detected(&status, true);
    storage_status_set_mount_result(&status, STORAGE_CORRUPT);
    storage_status_set_mount_result(&status, STORAGE_OK);

    TEST_ASSERT_EQUAL(CARD_READY, status.state);
    TEST_ASSERT_EQUAL(STORAGE_OK, status.last_fault);
}

/* ============ capacity ============ */

void test_percent_used_calculates_correctly(void)
{
    bring_card_to_ready(1000U, 250U, 0U);
    TEST_ASSERT_EQUAL_UINT8(75U, storage_status_percent_used(&status));
}

void test_percent_used_is_zero_for_empty_card(void)
{
    bring_card_to_ready(1000U, 1000U, 0U);
    TEST_ASSERT_EQUAL_UINT8(0U, storage_status_percent_used(&status));
}

void test_percent_used_is_100_for_full_card(void)
{
    bring_card_to_ready(1000U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT8(100U, storage_status_percent_used(&status));
}

void test_percent_used_is_zero_when_capacity_unknown(void)
{
    /* Guards against divide-by-zero before capacity has been read. */
    TEST_ASSERT_EQUAL_UINT8(0U, storage_status_percent_used(&status));
}

void test_free_space_exceeding_total_is_clamped(void)
{
    storage_status_set_capacity(&status, 1000U, 5000U);
    TEST_ASSERT_EQUAL_UINT32(1000U, status.free_kb);
    TEST_ASSERT_EQUAL_UINT8(0U, storage_status_percent_used(&status));
}

void test_percent_used_does_not_overflow_on_large_card(void)
{
    /* 32 GB card in kB - would overflow a 32-bit multiply by 100. */
    bring_card_to_ready(32000000U, 16000000U, 0U);
    TEST_ASSERT_EQUAL_UINT8(50U, storage_status_percent_used(&status));
}

void test_percent_used_null_status_returns_zero(void)
{
    TEST_ASSERT_EQUAL_UINT8(0U, storage_status_percent_used(NULL));
}

/* ============ permissions ============ */

void test_cannot_record_without_card(void)
{
    TEST_ASSERT_FALSE(storage_status_can_record(&status));
}

void test_cannot_record_when_unmounted(void)
{
    storage_status_set_card_detected(&status, true);
    TEST_ASSERT_FALSE(storage_status_can_record(&status));
}

void test_can_record_when_ready(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    TEST_ASSERT_TRUE(storage_status_can_record(&status));
}

void test_cannot_record_when_faulted(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    storage_status_report_fault(&status, STORAGE_WRITE_FAIL);
    TEST_ASSERT_FALSE(storage_status_can_record(&status));
}

void test_cannot_play_when_ready_but_no_files(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    TEST_ASSERT_FALSE(storage_status_can_play(&status));
}

void test_can_play_when_ready_with_files(void)
{
    bring_card_to_ready(1000U, 500U, 1U);
    TEST_ASSERT_TRUE(storage_status_can_play(&status));
}

void test_cannot_play_when_faulted_even_with_files(void)
{
    bring_card_to_ready(1000U, 500U, 5U);
    storage_status_report_fault(&status, STORAGE_CORRUPT);
    TEST_ASSERT_FALSE(storage_status_can_play(&status));
}

void test_permission_checks_reject_null(void)
{
    TEST_ASSERT_FALSE(storage_status_can_record(NULL));
    TEST_ASSERT_FALSE(storage_status_can_play(NULL));
}

/* ============ faults ============ */

void test_report_fault_sets_state_and_reason(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    storage_status_report_fault(&status, STORAGE_FULL);

    TEST_ASSERT_EQUAL(CARD_FAULT, status.state);
    TEST_ASSERT_EQUAL(STORAGE_FULL, status.last_fault);
}

void test_report_storage_ok_is_not_treated_as_a_fault(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    storage_status_report_fault(&status, STORAGE_OK);
    TEST_ASSERT_EQUAL(CARD_READY, status.state);
}

void test_report_fault_with_no_card_is_ignored(void)
{
    storage_status_report_fault(&status, STORAGE_WRITE_FAIL);
    /* Absence is the more specific condition and must not be masked. */
    TEST_ASSERT_EQUAL(CARD_ABSENT, status.state);
}

void test_clear_fault_returns_to_ready(void)
{
    bring_card_to_ready(1000U, 500U, 0U);
    storage_status_report_fault(&status, STORAGE_WRITE_FAIL);
    storage_status_clear_fault(&status);

    TEST_ASSERT_EQUAL(CARD_READY, status.state);
    TEST_ASSERT_EQUAL(STORAGE_OK, status.last_fault);
}

void test_clear_fault_when_not_faulted_does_nothing(void)
{
    storage_status_set_card_detected(&status, true);
    storage_status_clear_fault(&status);
    TEST_ASSERT_EQUAL(CARD_PRESENT_UNMOUNTED, status.state);
}

/* ============ UI view (what Tony's display consumes) ============ */

void test_ui_view_no_card(void)
{
    storage_ui_view_t view;
    TEST_ASSERT_EQUAL(STORAGE_OK, storage_status_get_ui_view(&status, &view));

    TEST_ASSERT_EQUAL_STRING("No Card", view.status_text);
    TEST_ASSERT_FALSE(view.record_enabled);
    TEST_ASSERT_FALSE(view.play_enabled);
    TEST_ASSERT_EQUAL_UINT32(0U, view.file_count);
}

void test_ui_view_card_present_but_unmounted(void)
{
    storage_status_set_card_detected(&status, true);

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_STRING("Card Not Ready", view.status_text);
    TEST_ASSERT_FALSE(view.record_enabled);
}

void test_ui_view_ready_with_files(void)
{
    bring_card_to_ready(1000U, 400U, 3U);

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_STRING("Ready", view.status_text);
    TEST_ASSERT_TRUE(view.record_enabled);
    TEST_ASSERT_TRUE(view.play_enabled);
    TEST_ASSERT_EQUAL_UINT32(3U, view.file_count);
    TEST_ASSERT_EQUAL_UINT8(60U, view.percent_used);
    TEST_ASSERT_FALSE(view.low_space_warning);
}

void test_ui_view_full_card_gets_distinct_wording(void)
{
    bring_card_to_ready(1000U, 0U, 2U);
    storage_status_report_fault(&status, STORAGE_FULL);

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_STRING("Card Full", view.status_text);
    TEST_ASSERT_FALSE(view.record_enabled);
}

void test_ui_view_generic_fault_wording(void)
{
    bring_card_to_ready(1000U, 500U, 2U);
    storage_status_report_fault(&status, STORAGE_CORRUPT);

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_STRING("Card Error", view.status_text);
}

void test_ui_view_low_space_warning_triggers_at_threshold(void)
{
    bring_card_to_ready(1000U, 100U, 1U); /* exactly 90% used */

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_UINT8(90U, view.percent_used);
    TEST_ASSERT_TRUE(view.low_space_warning);
    /* Recording is still permitted at the warning threshold. */
    TEST_ASSERT_TRUE(view.record_enabled);
}

void test_ui_view_low_space_warning_not_set_just_below_threshold(void)
{
    bring_card_to_ready(1000U, 110U, 1U); /* 89% used */

    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);

    TEST_ASSERT_EQUAL_UINT8(89U, view.percent_used);
    TEST_ASSERT_FALSE(view.low_space_warning);
}

void test_ui_view_low_space_warning_suppressed_when_no_card(void)
{
    storage_ui_view_t view;
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_FALSE(view.low_space_warning);
}

void test_ui_view_rejects_null_arguments(void)
{
    storage_ui_view_t view;
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, storage_status_get_ui_view(NULL, &view));
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, storage_status_get_ui_view(&status, NULL));
}

/* Multi-step: the full lifecycle the UI will actually observe. */
void test_ui_view_tracks_full_insert_use_remove_sequence(void)
{
    storage_ui_view_t view;

    /* 1. Powered on, no card */
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_EQUAL_STRING("No Card", view.status_text);
    TEST_ASSERT_FALSE(view.record_enabled);

    /* 2. User inserts a card */
    storage_status_set_card_detected(&status, true);
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_EQUAL_STRING("Card Not Ready", view.status_text);

    /* 3. Mount succeeds, capacity and file list read */
    storage_status_set_mount_result(&status, STORAGE_OK);
    storage_status_set_capacity(&status, 2000U, 1000U);
    storage_status_set_file_count(&status, 2U);
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_EQUAL_STRING("Ready", view.status_text);
    TEST_ASSERT_TRUE(view.record_enabled);
    TEST_ASSERT_TRUE(view.play_enabled);
    TEST_ASSERT_EQUAL_UINT32(2U, view.file_count);

    /* 4. A recording completes, file count grows */
    storage_status_set_file_count(&status, 3U);
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_EQUAL_UINT32(3U, view.file_count);

    /* 5. Card pulled out mid-use */
    storage_status_set_card_detected(&status, false);
    storage_status_get_ui_view(&status, &view);
    TEST_ASSERT_EQUAL_STRING("No Card", view.status_text);
    TEST_ASSERT_FALSE(view.record_enabled);
    TEST_ASSERT_FALSE(view.play_enabled);
    TEST_ASSERT_EQUAL_UINT32(0U, view.file_count);
}

/* ============ recording time remaining ============ */

void test_seconds_remaining_typical_case(void)
{
    /* 16 kHz, 16-bit mono = 32000 B/s. 1024 kB free = 1048576 bytes. */
    bring_card_to_ready(2000U, 1024U, 0U);
    uint32_t secs = storage_status_recording_seconds_remaining(&status, 16000U, 16U, 1U);
    TEST_ASSERT_EQUAL_UINT32(32U, secs);
}

void test_seconds_remaining_halves_for_stereo(void)
{
    bring_card_to_ready(2000U, 1024U, 0U);
    uint32_t mono = storage_status_recording_seconds_remaining(&status, 16000U, 16U, 1U);
    uint32_t stereo = storage_status_recording_seconds_remaining(&status, 16000U, 16U, 2U);
    TEST_ASSERT_EQUAL_UINT32(mono / 2U, stereo);
}

void test_seconds_remaining_is_zero_when_card_full(void)
{
    bring_card_to_ready(1000U, 0U, 0U);
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(&status, 16000U, 16U, 1U));
}

void test_seconds_remaining_rejects_invalid_format(void)
{
    bring_card_to_ready(2000U, 1024U, 0U);
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(&status, 0U, 16U, 1U));
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(&status, 16000U, 0U, 1U));
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(&status, 16000U, 16U, 0U));
    /* 12-bit is not a whole number of bytes per sample. */
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(&status, 16000U, 12U, 1U));
}

void test_seconds_remaining_rejects_null_status(void)
{
    TEST_ASSERT_EQUAL_UINT32(0U,
        storage_status_recording_seconds_remaining(NULL, 16000U, 16U, 1U));
}

void test_seconds_remaining_does_not_overflow_on_large_free_space(void)
{
    /* 32 GB free at 8 kHz 8-bit mono - free_bytes far exceeds 32 bits. */
    bring_card_to_ready(32000000U, 32000000U, 0U);
    uint32_t secs = storage_status_recording_seconds_remaining(&status, 8000U, 8U, 1U);
    TEST_ASSERT_EQUAL_UINT32(4096000U, secs);
}

int main(void)
{
    UNITY_BEGIN();

    RUN_TEST(test_init_starts_with_no_card);
    RUN_TEST(test_init_handles_null_safely);

    RUN_TEST(test_card_inserted_moves_to_present_unmounted);
    RUN_TEST(test_card_absent_stays_absent);
    RUN_TEST(test_reinserting_already_present_card_does_not_reset_ready_state);
    RUN_TEST(test_card_removal_clears_all_state);
    RUN_TEST(test_card_removal_while_faulted_clears_the_fault);
    RUN_TEST(test_remove_then_reinsert_requires_remount);

    RUN_TEST(test_successful_mount_moves_to_ready);
    RUN_TEST(test_failed_mount_moves_to_fault_with_reason);
    RUN_TEST(test_mount_attempt_with_no_card_is_ignored);
    RUN_TEST(test_remount_after_fault_returns_to_ready);

    RUN_TEST(test_percent_used_calculates_correctly);
    RUN_TEST(test_percent_used_is_zero_for_empty_card);
    RUN_TEST(test_percent_used_is_100_for_full_card);
    RUN_TEST(test_percent_used_is_zero_when_capacity_unknown);
    RUN_TEST(test_free_space_exceeding_total_is_clamped);
    RUN_TEST(test_percent_used_does_not_overflow_on_large_card);
    RUN_TEST(test_percent_used_null_status_returns_zero);

    RUN_TEST(test_cannot_record_without_card);
    RUN_TEST(test_cannot_record_when_unmounted);
    RUN_TEST(test_can_record_when_ready);
    RUN_TEST(test_cannot_record_when_faulted);
    RUN_TEST(test_cannot_play_when_ready_but_no_files);
    RUN_TEST(test_can_play_when_ready_with_files);
    RUN_TEST(test_cannot_play_when_faulted_even_with_files);
    RUN_TEST(test_permission_checks_reject_null);

    RUN_TEST(test_report_fault_sets_state_and_reason);
    RUN_TEST(test_report_storage_ok_is_not_treated_as_a_fault);
    RUN_TEST(test_report_fault_with_no_card_is_ignored);
    RUN_TEST(test_clear_fault_returns_to_ready);
    RUN_TEST(test_clear_fault_when_not_faulted_does_nothing);

    RUN_TEST(test_ui_view_no_card);
    RUN_TEST(test_ui_view_card_present_but_unmounted);
    RUN_TEST(test_ui_view_ready_with_files);
    RUN_TEST(test_ui_view_full_card_gets_distinct_wording);
    RUN_TEST(test_ui_view_generic_fault_wording);
    RUN_TEST(test_ui_view_low_space_warning_triggers_at_threshold);
    RUN_TEST(test_ui_view_low_space_warning_not_set_just_below_threshold);
    RUN_TEST(test_ui_view_low_space_warning_suppressed_when_no_card);
    RUN_TEST(test_ui_view_rejects_null_arguments);
    RUN_TEST(test_ui_view_tracks_full_insert_use_remove_sequence);

    RUN_TEST(test_seconds_remaining_typical_case);
    RUN_TEST(test_seconds_remaining_halves_for_stereo);
    RUN_TEST(test_seconds_remaining_is_zero_when_card_full);
    RUN_TEST(test_seconds_remaining_rejects_invalid_format);
    RUN_TEST(test_seconds_remaining_rejects_null_status);
    RUN_TEST(test_seconds_remaining_does_not_overflow_on_large_free_space);

    return UNITY_END();
}
